import std.io

pub type AppError = Failed(String)

pub fn bump(n: Int64) -> Int64 {
    return n + 1
}

pub fn main() effect io -> Result<(), AppError> {
    let v = bump(5) + 1
    if v == 7 { io.println("add-ok") } else { io.println("add-bad") }
    if bump(5) == 6 { io.println("cmp-ok") } else { io.println("cmp-bad") }
    if !(bump(0) == 1) { io.println("not-bad") } else { io.println("not-ok") }
    let w = bump(bump(1) + 1) + bump(2)
    if w == 7 { io.println("nested-ok") } else { io.println("nested-bad") }
    return Ok(())
}
